-- Who runs a meeting, and whether it is transcribed (generated by drizzle-kit,
-- then fixed per packages/db/REBUILDS.md).
--
-- Transcription becomes something people decide: an account default for the
-- meetings a user starts, and a meeting's own on/off. Both default to on, which
-- is what every meeting did before. Board edit approval moves onto the
-- admission. A meeting records the organizer of the schedule it fulfils, who
-- stands in as host while no owner or admin is present (added with ALTER, not
-- a rebuild of meetings and its dependents).
--
-- A Space's owner is stored once, on spaces.owner_user_id; their membership
-- becomes an ordinary admin row. space_members is referenced by no table, so
-- the plain rebuild is safe. Deploy window: until the new Worker is live, old
-- code that writes an 'owner' membership (creating a Space or personal Space,
-- transferring ownership) is refused by the new CHECK and succeeds on retry.
ALTER TABLE `users` ADD `transcribe_meetings` integer DEFAULT true NOT NULL;--> statement-breakpoint
ALTER TABLE `meeting_admissions` ADD `whiteboard_edit_granted` integer DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE `meetings` ADD `organizer_user_id` text REFERENCES users(id) ON DELETE SET NULL;--> statement-breakpoint
ALTER TABLE `meetings` ADD `transcription_enabled` integer DEFAULT true NOT NULL;--> statement-breakpoint
CREATE TABLE `__new_space_members` (
	`id` text PRIMARY KEY NOT NULL,
	`space_id` text NOT NULL,
	`user_id` text NOT NULL,
	`role` text DEFAULT 'member' NOT NULL,
	`joined_at` integer NOT NULL,
	CONSTRAINT `fk_space_members_space_id_spaces_id_fk` FOREIGN KEY (`space_id`) REFERENCES `spaces`(`id`) ON DELETE CASCADE,
	CONSTRAINT `fk_space_members_user_id_users_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
	CONSTRAINT "space_members_role_check" CHECK("role" in ('admin', 'member'))
);
--> statement-breakpoint
INSERT INTO `__new_space_members`(`id`, `space_id`, `user_id`, `role`, `joined_at`) SELECT `id`, `space_id`, `user_id`, CASE `role` WHEN 'owner' THEN 'admin' ELSE `role` END, `joined_at` FROM `space_members`;--> statement-breakpoint
DROP TABLE `space_members`;--> statement-breakpoint
ALTER TABLE `__new_space_members` RENAME TO `space_members`;--> statement-breakpoint
DROP INDEX IF EXISTS `space_members_single_owner_idx`;--> statement-breakpoint
CREATE INDEX `space_members_user_id_idx` ON `space_members` (`user_id`);--> statement-breakpoint
CREATE UNIQUE INDEX `space_members_unique_idx` ON `space_members` (`space_id`,`user_id`);--> statement-breakpoint
CREATE INDEX `meetings_organizer_user_id_idx` ON `meetings` (`organizer_user_id`);--> statement-breakpoint
